import hashlib,json,pathlib,runpy
H=pathlib.Path(__file__).resolve().parent;P='additional_rust_ooutwire_remaining';runpy.run_path(str(H/(P+'_synthesis02.py')));fs=json.loads((H/(P+'_scope.json')).read_text())['files'];p=H/(P+'.json');r=json.loads(p.read_text())
