rows=[{'id':'ROUT-F005','severity':'high','title':'Positive arity costs become negative or overflow in mu2','finding':'arity_sum casts each usize arity to i64 and sums without checks. On64-bit hosts NewForm(2^63) has negative secondary cost; two valid large i64 arities can overflow their sum. Bounds::validate imposes no arity ceiling. This breaks the declared nonnegative arity refinement on public Item inputs even before search allocates contexts.','evidence':[e(44,49,65),e(23,19,42)],'recommended_action':'Use a checked unsigned/arbitrary-precision cost representation or reject unrepresentable arities and sums before comparison; carry measure identity separately from numeric tuple.','validation':'ROUT-CHECK007 exact fixed-width arithmetic model, no native execution.'},{'id':'ROUT-F006','severity':'high','title':'Pruned minimum search omits repairs outside unstated engine preconditions','finding':'The two-instance pruning retains only deltas mentioning the target. A reachable rule-free base with six data, one unary form, instance(0,[0]), existing requirements(2,3),(4,5), and already-separated target(0,1) has four valid two-instance repairs that mention no target endpoint. No cost0/1 response works and no pruned cost2 response works, so the displayed min_responses algorithm returnsNone although the declared full space contains repairs. Engine use may maintain stronger invariants, but the public API validates only rule-freedom and max_items.','evidence':[e(33,96,140),e(46,96,134),e(58,54,65)],'recommended_action':'Enforce and document prior-requirement satisfaction/target-collapse premises, or fall back to complete enumeration for other valid bases; give malformed/precondition failures distinct from exhaustive no-response.','validation':'ROUT-CHECK008 independently enumerates the complete unary cost<=2 population, preserving all four omitted witnesses. No original/native code execution.'},{'id':'ROUT-F007','severity':'medium','title':'Closure round bound overflows before division','finding':'closure_round_bound multiplies n*(n-1) in usize before dividing by2. With64-bit n=2^32+1 the mathematical result fits usize, but intermediate multiplication overflows; checked builds panic and wrapping builds return the wrong smaller bound.','evidence':[e(30,42,45)],'recommended_action':'Divide the even factor first and use checked multiplication with explicit overflow refusal; distinguish mathematical round bound from actual feasible state size.','validation':'ROUT-CHECK009 exact arithmetic model only, no giant state or native execution.'}]
d={x['id']:x for x in r['findings']};d.update({x['id']:x for x in rows});r['findings']=list(d.values())
c={'id':'ROUT-C004','claim':'Within the declared valid finite search regime, minimum responses retain ties, quotient complete candidates by child structural key, and preserve class multiplicities. Fixed-data closure terminates within at most n(n-1)/2 successful rounds only when every round separates a previously collapsed pair and preserves earlier imposed requirements.','evidence':[e(46,70,161),e(30,8,23),e(58,158,203)],'dependencies':['Complete enumeration/pruning under all required base invariants','Representable correctly ordered cost values and canonicalization within budget','Response availability, fixed data and preservation of all previous demands'],'limitations':['No unique choice, physical dynamics or endogenous demand follows from tie classes','Public API gaps and numeric limits are recorded separately inF005–F007','Existing source test outcomes/counts are historical declarations, not fresh native evidence']};d={x['id']:x for x in r['claims']};d[c['id']]=c;r['claims']=list(d.values())
